import { sortBy, meanBy, sumBy, maxBy, minBy } from 'lodash';

// ✅ GOOD: Import specific functions (tree-shakes unused code)
import sortBy from 'lodash/sortBy';
import meanBy from 'lodash/meanBy';
import sumBy from 'lodash/sumBy';
import maxBy from 'lodash/maxBy';
import minBy from 'lodash/minBy';
```

### Bundle Size Impact
- Importing 5 functions from lodash: ~48 KB (minified)
- Full lodash: ~600 KB (minified)
- **Savings**: ~552 KB per page

## 2. Replace Heavy Libraries with Native APIs

**Problem**: Using libraries for functionality that JavaScript provides natively.

### Examples

```typescript
// ❌ BAD: Using lodash functions
import { mean, std, median, variance, quantileSeq } from 'mathjs';

const mean = mean(arr); // ~200 KB library

// ✅ GOOD: Native JavaScript for simple operations
const mean = arr => arr.reduce((a, b) => a + b, 0) / arr.length; // 0 KB

// Sort
// ❌ BAD: import { sortBy } from 'lodash';
const sorted = sortBy(arr, 'price');

// ✅ GOOD: Native Array.prototype.sort
const sorted = arr.sort((a, b) => a.price - b.price);
```

### Native Alternatives for Common Operations

```typescript
// Filtering
const inStock = products.filter(p => p.inStock);

// Finding max/min
const maxPrice = Math.max(...products.map(p => p.price));
const minPrice = Math.min(...products.map(p => p.price));
const bestRated = products.reduce((max, p) => p.rating > max.rating ? p : max);

// Grouping
const byCategory = products.reduce((acc, p) => {
  if (!acc[p.category]) acc[p.category] = [];
  acc[p.category].push(p);
  return acc;
}, {});

// Averaging
const avgPrice = products.reduce((sum, p) => sum + p.price, 0) / products.length;

// Summing
const totalReviews = products.reduce((sum, p) => sum + p.reviews, 0);
```

## 3. Dynamic Imports for Heavy Components

**Problem**: Loading all components upfront increases initial bundle.

```typescript
// ❌ BAD: Loads AdvancedAnalysis on home page load
import { AdvancedAnalysis } from './AdvancedAnalysis';

export default function Page() {
  const [tab, setTab] = useState('overview');
  return tab === 'advanced' ? <AdvancedAnalysis /> : <Overview />;
}

// ✅ GOOD: Load AdvancedAnalysis on demand
import dynamic from 'next/dynamic';

const AdvancedAnalysis = dynamic(
  () => import('./AdvancedAnalysis'),
  { loading: () => <div>Loading...</div> }
);

export default function Page() {
  const [tab, setTab] = useState('overview');
  return tab === 'advanced' ? <AdvancedAnalysis /> : <Overview />;
}
```

## 4. Code Splitting by Route

**Problem**: Bundling all pages together increases initial load.

```typescript
// ✅ GOOD: Next.js automatically code-splits by page
src/app/page.tsx // /
src/app/compare/page.tsx // /compare

// Each page's code is in separate chunks
// Only the home page code loads for / requests
```

## 5. Remove Unused Dependencies

```typescript
// ❌ BAD: Installed but not used
"mathjs": "^12.2.1",
"lodash": "^4.17.21",

// ✅ GOOD: Remove and use native alternatives
npm uninstall mathjs lodash
```

## 6. Minification and Compression

```javascript
// next.config.js
module.exports = {
  compress: true, // Enable gzip compression
  productionBrowserSourceMaps: false, // Don't bundle source maps
};
```

## 7. Image Optimization

```typescript
// ❌ BAD: Large image files
<img src="/large-image.png" width="200" />

// ✅ GOOD: Use Next.js Image with optimization
import Image from 'next/image';
<Image src="/large-image.png" width={200} height={200} />
// Automatically: resizes, converts to WebP, lazy loads
```

## Bundle Analysis Tools

### 1. Webpack Bundle Analyzer
```bash
npm install --save-dev @next/bundle-analyzer

# next.config.js
const withBundleAnalyzer = require('@next/bundle-analyzer')({
  enabled: process.env.ANALYZE === 'true',
});
module.exports = withBundleAnalyzer({});

# Run analysis
ANALYZE=true npm run build
```

### 2. Import Cost (VS Code Extension)
Shows bundle size of imports inline in your editor.

## Performance Targets

- Initial JS bundle: < 100 KB
- Page-specific code: < 50 KB
- Third-party libraries: < 50 KB
- Total: < 200 KB before compression

## Optimization Checklist

- [ ] Use specific imports (import X from 'lib/x')
- [ ] Replace heavy libs with native alternatives
- [ ] Dynamic import heavy components
- [ ] Remove unused dependencies
- [ ] Enable compression in build config
- [ ] Analyze bundle regularly

