'use client';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  reviews: number;
  inStock: boolean;
}

// Statistics functions
function mean(arr: number[]): number {
  if (arr.length === 0) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function median(arr: number[]): number {
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function std(arr: number[]): number {
  const m = mean(arr);
  const variance = arr.reduce((acc, val) => acc + Math.pow(val - m, 2), 0) / arr.length;
  return Math.sqrt(variance);
}

function variance(arr: number[]): number {
  const m = mean(arr);
  return arr.reduce((acc, val) => acc + Math.pow(val - m, 2), 0) / arr.length;
}

function quantileSeq(arr: number[], q: number): number {
  const sorted = [...arr].sort((a, b) => a - b);
  const index = q * (sorted.length - 1);
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  const weight = index - lower;

  if (lower === upper) {
    return sorted[lower];
  }
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
}

function sortBy<T>(arr: T[], key: keyof T): T[] {
  return [...arr].sort((a, b) => {
    const aVal = a[key];
    const bVal = b[key];
    if (aVal < bVal) return -1;
    if (aVal > bVal) return 1;
    return 0;
  });
}

export function AdvancedAnalysis({ products }: { products: Product[] }) {
  // Using native functions for statistical calculations
  const prices = products.map(p => p.price);
  const ratings = products.map(p => p.rating);
  const reviews = products.map(p => p.reviews);

  const priceStats = {
    mean: mean(prices),
    median: median(prices),
    std: std(prices),
    variance: variance(prices),
    q1: quantileSeq(prices, 0.25),
    q3: quantileSeq(prices, 0.75),
  };

  const ratingStats = {
    mean: mean(ratings),
    median: median(ratings),
    std: std(ratings),
  };

  const reviewStats = {
    mean: mean(reviews),
    median: median(reviews),
    std: std(reviews),
  };

  // Calculate value score: rating / price * 100
  const valueScores = products.map(p => ({
    name: p.name,
    score: (p.rating / p.price) * 100,
  }));
  const sortedByValue = sortBy(valueScores, 'score').reverse();

